    "cat-education.html", "cat.education.count", "research-models", "5 เครื่องมือ · พร้อมนำร่อง 3 · ทดลอง 2 · สาธิต 0", "5 tools · pilot-ready 3 · experimental 2 · demo 0", "5 个工具 · 可试点 3 · 实验性 2 · 演示 0", "",
    "cat-education.html", "cat.st.pilot-ready", "_platform", "พร้อมนำร่อง", "Pilot-ready", "可试点", "",
